const { query, newId } = require("./db");

/**
 * Writes a notification row.
 *
 * Two rules are enforced here rather than at each call site, so they can't be
 * forgotten:
 *
 *  1. Self-notifications are skipped. Liking your own diagram or replying to
 *     your own comment produces nothing.
 *  2. Failures never propagate. A notification is a side effect of an action,
 *     not the action itself — if writing one fails, the like or comment that
 *     triggered it must still succeed. Errors are logged and swallowed.
 *
 * Deduplication: for like-type events we clear any previous unread row for the
 * same actor/target first, so repeatedly unliking and re-liking can't stack up
 * a pile of identical notifications.
 *
 * @param {object} n
 * @param {string} n.recipientId  who receives it
 * @param {string} n.actorId      who caused it
 * @param {string} n.type         diagram_like | diagram_comment | comment_reply | comment_like
 * @param {string} [n.diagramId]
 * @param {string} [n.commentId]
 * @param {string} [n.preview]    short text snippet shown in the list
 */
async function notify({ recipientId, actorId, type, diagramId = null, commentId = null, preview = null }) {
  try {
    if (!recipientId || !actorId || !type) return;
    if (recipientId === actorId) return; // rule 1

    // rule 3 — honour the recipient's notification preferences. These are
    // stored on the user row and set from the Settings page. Checked here, at
    // the single choke point, so no call site can forget to.
    const PREF_COLUMN = {
      diagram_like: "notify_on_like",
      comment_like: "notify_on_like",
      diagram_comment: "notify_on_comment",
      comment_reply: "notify_on_comment",
      new_follower: "notify_on_follow",
      follow_request: "notify_on_follow",
      // follow_accepted is deliberately absent: being told your own request
      // was accepted is a direct response to an action you took, not a
      // notification about someone else's activity, so it always sends.
    };
    const prefColumn = PREF_COLUMN[type];
    if (prefColumn) {
      const { rows: prefRows } = await query(
        `SELECT ${prefColumn} AS enabled FROM users WHERE user_id = :recipientId`,
        { recipientId }
      );
      // Default to sending if the user row is missing the column value —
      // silently swallowing notifications is worse than one extra bell.
      if (prefRows.length && Number(prefRows[0].enabled) === 0) return;
    }

    // Collapse repeat like events rather than accumulating duplicates.
    if (type === "diagram_like" || type === "comment_like") {
      await query(
        `DELETE FROM notifications
         WHERE recipient_id = :recipientId AND actor_id = :actorId AND type = :type
           AND is_read = FALSE
           AND (diagram_id <=> :diagramId) AND (comment_id <=> :commentId)`,
        { recipientId, actorId, type, diagramId, commentId }
      );
    }

    await query(
      `INSERT INTO notifications
         (notification_id, recipient_id, actor_id, type, diagram_id, comment_id, preview)
       VALUES (:notificationId, :recipientId, :actorId, :type, :diagramId, :commentId, :preview)`,
      {
        notificationId: newId("ntf"),
        recipientId,
        actorId,
        type,
        diagramId,
        commentId,
        preview: preview ? String(preview).slice(0, 200) : null,
      }
    );
  } catch (err) {
    // rule 2 — log, never throw.
    console.error("notify() failed (non-fatal):", err && err.message ? err.message : err);
  }
}

module.exports = { notify };
